+uint8_t
+dlc_to_data_length(uint8_t dlc)
+{
+    if (dlc <= 8)
+        return dlc;
+
+    switch (dlc)
+    {
+    case 9:  return 12;
+    case 10: return 16;
+    case 11: return 20;
+    case 12: return 24;
+    case 13: return 32;
+    case 14: return 48;
+    case 15: return 64;
+    default: return 0;
+    }
+}
